    "RLE run length is too large.": {"ru": "Слишком большая длина повтора RLE.", "uk": "Завеликий RLE-повтор."},
    "Invalid RLE run length.": {"ru": "Некорректная длина серии RLE.", "uk": "Некоректна довжина RLE-серії."},
    "Unexpected data after the end of RLE.": {"ru": "Лишние данные после конца RLE.", "uk": "Зайві дані після кінця RLE."},
    "RLE exceeds the specified height.": {"ru": "RLE выходит за указанную высоту.", "uk": "RLE виходить за вказану висоту."},
